+        calendar.querySelectorAll(".react-datepicker__navigation--next"),
+      ).toHaveLength(1);
+    });
+
+    it("renders a header in every month after the weekday names when positioned in the middle", () => {
+      const { calendar, instance } = getCalendar({
+        monthsShown: 2,
+        monthHeaderPosition: "middle",
