+        const header = safeQuerySelector(
+          monthContainer,
+          ".react-datepicker__header",
+        );
+        const month = safeQuerySelector(
+          monthContainer,
+          ".react-datepicker__month",
+        );
+
+        expect(dayNames.compareDocumentPosition(header)).toBe(
+          Node.DOCUMENT_POSITION_FOLLOWING,
